# Generated by build.py from recipe.yml for recipe http-find-the-request-that-failed. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'make-reports.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The reports the client run fetches: site/ has 1 to 50 but 37, mirror/ has 1 to 36.`nmkdir -p site/reports mirror/reports`nn=1`nwhile [ `"`$n`" -le 50 ]; do`n  if [ `"`$n`" -ne 37 ]; then printf 'id,total\n%s,40\n' `"`$n`" > `"site/reports/report-`$n.csv`"; fi`n  if [ `"`$n`" -le 36 ]; then cp `"site/reports/report-`$n.csv`" mirror/reports/; fi`n  n=`$((n + 1))`ndone`n")
[IO.File]::WriteAllText((Join-Path $PWD 'narrow.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Narrows surl's verbose log to each answer of 400 or more and the request that caused it.`n# Exits 0 when it found one, 1 when every answer was below 400.`n# Run: sh narrow.sh [surl.log]    (needs a POSIX shell: Git Bash on Windows)`nlog=`${1:-surl.log}`n`n# The log is whole once every exchange that opened has ended: wait for that, at most 10 s.`ntries=0`nuntil [ `"`$(grep -c ' opened: ' `"`$log`")`" -eq `"`$(grep -c ' ended; ' `"`$log`")`" ]; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 50 ]; then echo `"the exchanges in `$log did not end within 10 s`"; exit 1; fi`n  sleep 0.2`ndone`n`n# Each log line is '#N <' (received), '#N >' (sent) or '#N *' (an event), then the text.`n# Keep the lines of the request being read; on an event that answered 400 or more, print`n# them, the event, and the head of the answer that follows (without its Date).`nawk '`n  { sub(/\r`$/, `"`"); text = `$0; sub(/^#[0-9]+ . /, `"`", text); sub(/\\r\\n`$/, `"`", text) }`n  `$2 == `"<`" && `$3 ~ /^[A-Z]+`$/ && `$NF ~ /^HTTP\/1\.[01]/ { requests++; request = `"`" }`n  `$2 == `"<`" && text != `"`" { request = request `"> `" text `"\n`" }`n  `$2 == `"*`" && (text ~ /: [45][0-9][0-9], / || text ~ /answered [45][0-9][0-9]/) {`n    failed++`n    printf `"request %d of the run, exchange %s\n%s* %s\n`", requests, `$1, request, text`n    showing = 1; next`n  }`n  showing && `$2 == `">`" {`n    if (text == `"`") { showing = 0; print `"`" } else if (text !~ /^Date: /) print `"< `" text`n  }`n  END { printf `"%d requests, %d answered 400 or more\n`", requests, failed; exit (failed ? 0 : 1) }`n' `"`$log`"`n")
cmd /c 'sh make-reports.sh'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '-v', '--log-file', 'clean.log', '--directory', 'mirror', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh narrow.sh surl.log } finally { Stop-Process $server0; Stop-Process $server1 }
